from sim import Sim
import numpy as np

def run(ctrl,steps=300):
    sim=Sim(); sim.data.ctrl[:]=ctrl
    xs=[]; zs=[]
    for _ in range(steps):
        sim.step(1); xs.append(sim.pelvis_position()[0]); zs.append(sim.pelvis_position()[2])
    return xs[-1],max(xs),min(xs),min(zs),sim.torso_up(),sim.pelvis_position(),sim.box_position()

names=Sim().actuator_names()
for idx in [2,3,4,7,8,9,10]:
    for t in [-80,-40,-20,20,40,80]:
        c=np.zeros(19); c[idx]=t
        xf,xmax,xmin,zmin,tu,p,b=run(c)
        print(idx,names[idx],t,'xf',round(xf,3),'xmax',round(xmax,3),'xmin',round(xmin,3),'zmin',round(zmin,3),'tu',round(tu,3))
PY"

